// Seeds ONE fictional job and TWELVE fictional applicants. No real people, no database access.
// Recruiter settings (weights + threshold) arrive from the Telegram controller; manual runs use defaults.
const input = ($input.first() && $input.first().json) || {};
const s = input.settings;
const usingDefaults = !s;
const weights = (s && s.weights) || { skills: 40, experience: 30, education: 30 };
const threshold = (s && Number.isFinite(s.threshold)) ? s.threshold : 70;
const job = {
  id: 'RECRUITER-DEMO-JOB-01',
  title: 'Junior Software Developer Intern',
  company: 'Demo Startup (fictional)',
  minimumEducation: 'Bachelor',
  minimumExperienceYears: 1,
  requiredSkills: ['JavaScript', 'React', 'SQL'],
  weights,
  threshold
};
const candidates = [
  { id: 'RC001', name: 'Candidate A (fictional)', education: 'Master', experienceYears: 2, skills: ['JavaScript', 'React', 'SQL'] },
  { id: 'RC002', name: 'Candidate B (fictional)', education: 'Bachelor', experienceYears: 1, skills: ['JavaScript', 'React'] },
  { id: 'RC003', name: 'Candidate C (fictional)', education: 'High School', experienceYears: 4, skills: ['JavaScript', 'React', 'SQL'] },
  { id: 'RC004', name: 'Candidate D (fictional)', education: 'Bachelor', experienceYears: 3, skills: ['JavaScript', 'SQL'] },
  { id: 'RC005', name: 'Candidate E (fictional)', education: 'Bachelor', experienceYears: 0, skills: ['JavaScript'] },
  { id: 'RC006', name: 'Candidate F (fictional)', education: 'Master', experienceYears: 1, skills: ['React', 'SQL', 'Python'] },
  { id: 'RC007', name: 'Candidate G (fictional)', education: 'PhD', experienceYears: 0, skills: ['Python', 'SQL'] },
  { id: 'RC008', name: 'Candidate H (fictional)', education: 'Bachelor', experienceYears: 2, skills: ['JavaScript', 'React', 'SQL', 'Node.js'] },
  { id: 'RC009', name: 'Candidate I (fictional)', education: 'Associate', experienceYears: 2, skills: ['JavaScript', 'React'] },
  { id: 'RC010', name: 'Candidate J (fictional)', education: 'Master', experienceYears: 0, skills: ['JavaScript', 'React', 'SQL'] },
  { id: 'RC011', name: 'Candidate K (fictional)', education: 'Bachelor', experienceYears: 1, skills: ['React'] },
  { id: 'RC012', name: 'Candidate L (fictional)', education: 'Bachelor', experienceYears: 5, skills: ['SQL', 'Python'] }
];
return [{ json: { job, candidates, allSynthetic: true, usingDefaults } }];

// Quality gate: every fictional applicant must be scored or excluded exactly once.
// With default settings, also run a regression check on the known-correct result.
const x = $input.first().json;
const seed = $('Seed Fictional Recruiter Job and Candidates').first().json;
if (!x.allSynthetic || !Array.isArray(x.allEvaluations) || !Array.isArray(x.excluded)) {
  throw new Error('Unexpected recruiter engine output.');
}
const ids = x.allEvaluations.map(c => c.id).concat(x.excluded.map(c => c.id));
if (new Set(ids).size !== ids.length || ids.length !== seed.candidates.length) {
  throw new Error('Every candidate must be scored or excluded exactly once.');
}
if (seed.usingDefaults && (x.allEvaluations[0].id !== 'RC001' || !x.excluded.some(c => c.id === 'RC003'))) {
  throw new Error('Default-settings regression check failed.');
}
return [{ json: { testPassed: true, topThree: (x.shortlist || []).map(c => c.id), scores: (x.shortlist || []).map(c => c.score),
  excluded: x.excluded, belowThreshold: x.otherEligible, message: x.message,
  job: x.job, shortlist: x.shortlist, allEvaluations: x.allEvaluations, totalCandidates: x.totalCandidates,
  scoringMethod: x.scoringMethod, allSynthetic: true, usingDefaults: seed.usingDefaults,
  settings: { weights: x.weights, threshold: x.threshold },
  candidateNames: seed.candidates.map(c => ({ id: c.id, name: c.name })) } }];
